fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box), open the Data Explorer app, then go to its Dashboards section. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) view-mode-toggle — in the browser toolbar there is a two-button view toggle (a grid/'grip' icon for Card View and a lines/'list' icon for List View); click List View then Card View and confirm the dashboard listing re-renders in the two different layouts (cards in a grid vs. rows with Name / Type / Modified columns) with the active toggle button highlighted; (2) multi-select — click the 'Select' button (check-double icon) to enter multi-select mode, confirm selection checkboxes appear on the cards/rows and the toolbar switches to a selection toolbar showing an 'N selected' count plus Select-all, Move, Delete, and Exit controls, then select an item and confirm the count updates. Either layout may show an empty-state if there are no dashboards. You do NOT need to move or delete anything. Keep going until both sections are done. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "view-mode-toggle",
      "instruction": "toggle Card/List view modes",
      "visualCriteria": [
        "The Dashboards toolbar has both a Card View and a List View toggle button; clicking List View re-renders the listing as rows with column headers (Name / Type / Modified) and Card View re-renders it as a grid of cards, with the active mode's button visually highlighted (an empty-state is acceptable if there are no dashboards)"
      ]
    },
    {
      "name": "multi-select",
      "instruction": "enter multi-select bulk-actions mode",
      "visualCriteria": [
        "Clicking 'Select' enters selection mode: checkboxes appear on items and a selection toolbar showing an 'N selected' count plus Select-all / Move / Delete / Exit controls replaces the normal actions, and selecting an item updates the count (a valid empty-state is acceptable if there are no dashboards)"
      ]
    }
  ]
}
